        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "current": {
          "condition": {
            "type": "string",
            "description": "当前天气现象，例如晴、多云或小雨。",
            "sampleValue": "多云"
          },
          "temperatureText": {
            "type": "string",
            "description": "适合直接显示的当前温度文本。",
            "sampleValue": "26°C"
          },
          "humidityPercent": {
            "type": "number",
            "description": "当前相对湿度百分比。",
            "sampleValue": 58
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_electricity.png",
      "description": "低电模式电池图标，适合在淡绿色电量卡片中作为左侧主视觉。"
    }
  ]
}

